using System;
using System.IO;
using System.Text;
using UnityEditor;
using UnityEngine;
using UnityEngine.UIElements;
namespace ZeroToMillionaire.Editor {
 [InitializeOnLoad] public static class OnboardingPolishAuditV06 {
  const string Active="ZTM_ONBOARDING_POLISH_V06";
  static GameView view;static RenderTexture target;static int viewport,phase,warm,spins,replayStep,frame0;static double start,phaseStart;static bool context;static PlayerState replayBefore;static StringBuilder report=new StringBuilder();
  static string Root=>Directory.GetParent(Application.dataPath).FullName;
  static OnboardingPolishAuditV06(){EditorApplication.update+=Tick;}
  public static string Start(){if(EditorApplication.isPlaying)throw new Exception("Own Editor already playing");view=null;viewport=phase=warm=spins=replayStep=0;context=false;report.Clear();start=EditorApplication.timeSinceStartup;Environment.SetEnvironmentVariable("ZTM_QA_SAVE_DIR",Path.Combine(Root,".tooling","onboarding-v0.6-private-save"));UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/Scenes/Level1.unity");SessionState.SetBool(Active,true);EditorApplication.EnterPlaymode();return "queued";}
  static void Check(bool ok,string text){if(!ok)throw new Exception(text);report.AppendLine("PASS "+text);}
  static VisualElement UI=>view.GetComponent<UIDocument>().rootVisualElement;
  static bool Busy=>view.QaSpinning||UI.Q<VisualElement>("reward-to-task").resolvedStyle.display==DisplayStyle.Flex;
  static void Target(int w,int h){if(target!=null){view.GetComponent<UIDocument>().panelSettings.targetTexture=null;target.Release();UnityEngine.Object.Destroy(target);}target=new RenderTexture(w,h,0,RenderTextureFormat.ARGB32);target.Create();view.GetComponent<UIDocument>().panelSettings.targetTexture=target;}
  static void Set(PlayerState s){view.SetQaState(s,0);warm=0;phaseStart=EditorApplication.timeSinceStartup;}
  static bool Warm(){return ++warm>35&&EditorApplication.timeSinceStartup-phaseStart>.35;}
  static void Capture(string name){var old=RenderTexture.active;RenderTexture.active=target;var tex=new Texture2D(target.width,target.height,TextureFormat.RGBA32,false);tex.ReadPixels(new Rect(0,0,target.width,target.height),0,0);tex.Apply();File.WriteAllBytes(Path.Combine(Root,"Evidence","onboarding-v0.6-"+name+"-"+target.width+"x"+target.height+".png"),tex.EncodeToPNG());UnityEngine.Object.Destroy(tex);RenderTexture.active=old;report.AppendLine("CAPTURE "+name+" frame="+Time.frameCount+" size="+target.width+"x"+target.height);}
  static void Layout(){var b=UI.Q<VisualElement>("heroine-dialogue");var w=UI.Q<Label>("dialogue-text");Check(b.resolvedStyle.display==DisplayStyle.Flex,"dialogue visible");Check(b.worldBound.xMin>=UI.worldBound.xMin&&b.worldBound.xMax<=UI.worldBound.xMax,"bubble horizontal bounds");Check(!b.worldBound.Overlaps(UI.Q<VisualElement>("reels").worldBound),"dialogue avoids reels");Check(!b.worldBound.Overlaps(UI.Q<VisualElement>("active-quest")?.worldBound??Rect.zero),"dialogue avoids quest meters");foreach(var name in new[]{"tutorial-next","tutorial-skip"}){var button=UI.Q<Button>(name);if(button.resolvedStyle.display==DisplayStyle.Flex)Check(button.worldBound.height>=43.5f&&b.worldBound.Contains(button.worldBound.center),name+" touch target44");}var measured=w.MeasureTextSize(w.text,w.contentRect.width,VisualElement.MeasureMode.Exactly,0,VisualElement.MeasureMode.Undefined);Check(measured.y<=w.contentRect.height+1,"speech text fits measured="+measured.y+" available="+w.contentRect.height);Check(UI.Q<Image>("dialogue-portrait").image!=null,"existing heroine portrait reused");Check(PixelUi.FaceTravel(UI.Q<Button>("spin"))>=0,"raised spin retained");}
  static bool Same(PlayerState a,PlayerState b){if(a.cash!=b.cash||a.spins!=b.spins||a.freeSpins!=b.freeSpins||a.recoveries!=b.recoveries)return false;for(int i=0;i<8;i++)if(a.fragments[i]!=b.fragments[i]||a.purchased[i]!=b.purchased[i])return false;return true;}
  static PlayerState Milestone(int count){var s=new PlayerState{cash=170,spins=15};s.tutorial.completed=true;for(int i=0;i<count;i++)s.purchased[i]=true;return s;}
  static void Tick(){if(!SessionState.GetBool(Active,false)||!EditorApplication.isPlaying)return;try{if(start==0)start=EditorApplication.timeSinceStartup;if(view==null){view=UnityEngine.Object.FindFirstObjectByType<GameView>();if(view==null)return;frame0=Time.frameCount;}if(EditorApplication.timeSinceStartup-start>240)throw new Exception("feature audit timeout");
   if(phase==0){Target(viewport<2?360:480,viewport==0?640:viewport==1?800:960);Set(new PlayerState());phase=1;}
   else if(phase==1&&Warm()){Layout();Capture("initial");if(++viewport<3){phase=0;return;}var before=view.Model.Snapshot;view.QaClick("tutorial-next");Check(Same(before,view.Model.Snapshot),"NEXT grants no resources");Check(TutorialPolicy.Step(view.Model.Snapshot)==1,"first next invites spin");phase=2;warm=0;}
   else if(phase==2&&Warm()){Check(UI.Q<VisualElement>("tutorial-highlight")!=null,"spin highlight present");Capture("spin-invitation");view.QaClick("spin");view.QaClick("spin");Check(view.Model.Snapshot.spins==1,"repeated spin commits once");phase=3;warm=0;}
   else if(phase==3&&!Busy&&Warm()&&UI.Q<VisualElement>("heroine-dialogue").resolvedStyle.display==DisplayStyle.Flex){Layout();if(!context){Check(TutorialPolicy.Step(view.Model.Snapshot)==2,"after spin explains separate meters");Capture("contextual-meters");view.QaClick("tutorial-next");Check(!TutorialPolicy.CanNext(view.Model.Snapshot),"waits for both resources after meter explanation");context=true;}if(view.Model.CanBuy(0)){Check(TutorialPolicy.Step(view.Model.Snapshot)==3,"ready buy instruction requires both");Capture("ready-first-buy");int cash=view.Model.Snapshot.cash;view.QaClick("buy-0");view.QaBuy(0);Check(view.Model.PurchasedCount==1&&view.Model.Snapshot.cash==cash-view.Model.Definition(0).CashPrice,"actual manual buy once");phase=4;warm=0;phaseStart=EditorApplication.timeSinceStartup;}else{view.QaClick("spin");if(++spins>30)throw new Exception("first buy pacing timeout");warm=0;}}
   else if(phase==4&&Warm()&&UI.Q<VisualElement>("heroine-dialogue").resolvedStyle.display==DisplayStyle.Flex){Check(TutorialPolicy.Step(view.Model.Snapshot)==4,"first purchase advances dialogue");Layout();Capture("first-repair");view.QaClick("tutorial-next");Check(view.Model.Snapshot.tutorial.completed,"tutorial completion persisted");string notice;var loaded=new SaveStore(Path.Combine(Environment.GetEnvironmentVariable("ZTM_QA_SAVE_DIR"),"level1-v1.json"),new UnityStateCodec()).Load(out notice);Check(loaded.tutorial.completed&&Same(loaded,view.Model.Snapshot),"dialogue/save resources survive reload");Set(new PlayerState());phase=5;}
   else if(phase==5&&Warm()){var before=view.Model.Snapshot;view.QaClick("tutorial-skip");Check(view.Model.Snapshot.tutorial.skipped&&Same(before,view.Model.Snapshot),"skip saves without rewards");view.QaClick("menu");view.QaClick("tutorial-replay");replayBefore=view.Model.Snapshot;phase=6;warm=0;phaseStart=EditorApplication.timeSinceStartup;}
   else if(phase==6&&Warm()){Layout();Check(Same(replayBefore,view.Model.Snapshot),"help replay no resource changes step"+replayStep);Check(view.Model.Snapshot.tutorial.skipped,"replay cannot reopen saved intro");view.QaClick("tutorial-next");warm=0;phaseStart=EditorApplication.timeSinceStartup;if(++replayStep>4){Set(Milestone(2));view.QaClick("menu");phase=70;}}
   else if(phase==70&&Warm()){Check(view.Model.Snapshot.tutorial.storySeenMask==0,"menu does not consume pending story");Check(UI.Q<VisualElement>("heroine-dialogue").resolvedStyle.display==DisplayStyle.None,"menu pauses dialogue");var modal=UI.Q<VisualElement>("settings");Check(modal.worldBound.yMax<=UI.worldBound.yMax,"Russian menu fits viewport");Capture("menu");view.QaClick("close-settings");phase=7;warm=0;phaseStart=EditorApplication.timeSinceStartup;}
    else if(phase==7&&Warm()){Layout();Check(view.Model.Snapshot.tutorial.storySeenMask==0,"story is not seen before dismissal");Capture("milestone-surfaces");var undismissed=view.Model.Snapshot;Set(undismissed);phase=71;}
   else if(phase==71&&Warm()){Layout();Check(view.Model.Snapshot.tutorial.storySeenMask==0,"undismissed story survives reload fixture");view.QaClick("tutorial-next");Check(view.Model.Snapshot.tutorial.storySeenMask==1,"meaningful dismissal persists seen mask");Set(view.Model.Snapshot);phase=8;}
    else if(phase==8&&Warm()){Check(UI.Q<VisualElement>("heroine-dialogue").resolvedStyle.display==DisplayStyle.None,"seen story does not repeat on reload");Set(Milestone(8));phase=9;}
   else if(phase==9&&Warm()){Layout();Check(view.Model.Complete&&view.Model.Snapshot.tutorial.storySeenMask==0,"final story waits for dismissal");Capture("milestone-complete");view.QaClick("tutorial-next");Check(view.Model.Snapshot.tutorial.storySeenMask==15,"final dismissal acknowledges backlog once");view.QaShowReset();view.QaCancelReset();Check(view.Model.Complete,"reset cancel preserves complete");view.QaShowReset();view.QaConfirmReset();Check(view.Model.PurchasedCount==0&&view.Model.Snapshot.freeSpins==3,"confirmed reset returns fresh");warm=0;phaseStart=EditorApplication.timeSinceStartup;phase=10;}
   else if(phase==10&&Warm()){Check(TutorialPolicy.Step(view.Model.Snapshot)==0&&UI.Q<Label>("dialogue-text").text==TutorialPolicy.Steps[0],"reset clears volatile story and restores introduction");Check(Time.frameCount-frame0>100,"real advancing runtime frames="+(Time.frameCount-frame0));Finish(true);}
  }catch(Exception e){report.AppendLine("FAIL "+e);Debug.LogException(e);Finish(false);}}
  static void Finish(bool passed){SessionState.SetBool(Active,false);report.AppendLine("RESULT "+(passed?"PASS":"FAIL")+" elapsed="+(EditorApplication.timeSinceStartup-start).ToString("F2")+"; Editor UI callbacks; no physical input");File.WriteAllText(Path.Combine(Root,"Evidence","onboarding-v0.6-ui-checks.txt"),report.ToString());if(target!=null){view.GetComponent<UIDocument>().panelSettings.targetTexture=null;target.Release();UnityEngine.Object.Destroy(target);target=null;}EditorApplication.ExitPlaymode();Debug.Log("ZTM_ONBOARDING_POLISH_V06 "+passed);}
 }
}
